const fs=require('fs'),p=require('path'),os=require('os'),http=require('http'),{spawn}=require('child_process');
const root=process.cwd(),profile=fs.mkdtempSync(p.join(os.tmpdir(),'cwv24-'));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const types={'.html':'text/html; charset=utf-8','.css':'text/css','.js':'text/javascript','.json':'application/json','.webp':'image/webp','.jpg':'image/jpeg','.png':'image/png','.svg':'image/svg+xml','.ttf':'font/ttf','.woff2':'font/woff2'};
const server=http.createServer((req,res)=>{let f=p.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(fs.existsSync(f)&&fs.statSync(f).isDirectory())f=p.join(f,'index.html');if(!f.startsWith(root+'/')||!fs.existsSync(f)||!fs.statSync(f).isFile()){res.writeHead(404);return res.end();}res.setHeader('Content-Type',types[p.extname(f)]||'application/octet-stream');res.setHeader('Cache-Control','no-store');fs.createReadStream(f).pipe(res);});
let chrome,ws;
async function main(){
 await new Promise(r=>server.listen(0,'127.0.0.1',r));
 chrome=spawn((process.env.CHROME_BIN || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'),['--headless','--disable-gpu','--no-first-run','--no-default-browser-check','--disable-background-networking','--disable-extensions','--host-resolver-rules=MAP * ~NOTFOUND, EXCLUDE 127.0.0.1','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
 const pf=p.join(profile,'DevToolsActivePort');for(let i=0;i<100&&!fs.existsSync(pf);i++)await sleep(100);
 const port=fs.readFileSync(pf,'utf8').split('\n')[0];const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise((r,j)=>{ws.addEventListener('open',r,{once:true});ws.addEventListener('error',j,{once:true})});
 let id=0,pend=new Map();ws.addEventListener('message',e=>{const o=JSON.parse(e.data);if(o.id&&pend.has(o.id)){const z=pend.get(o.id);pend.delete(o.id);o.error?z.reject(o.error):z.resolve(o.result);}});
 const cmd=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pend.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
 await cmd('Page.enable');await cmd('Runtime.enable');await cmd('Network.enable');await cmd('Network.setCacheDisabled',{cacheDisabled:true});await cmd('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await cmd('Emulation.setCPUThrottlingRate',{rate:4});await cmd('Network.emulateNetworkConditions',{offline:false,latency:100,downloadThroughput:200000,uploadThroughput:93750});await cmd('Network.setBlockedURLs',{urls:['https://*','http://fonts.*']});
 await cmd('Page.addScriptToEvaluateOnNewDocument',{source:`window.__perf={lcp:0,element:'',cls:0,shift:[],long:[],fcp:0,vis:0};const o=(type,fn)=>{try{new PerformanceObserver(l=>l.getEntries().forEach(fn)).observe({type,buffered:true})}catch{}};o('largest-contentful-paint',e=>{__perf.lcp=e.startTime;__perf.element=e.element?.id||e.element?.className?.toString()||e.element?.tagName||''});o('layout-shift',e=>{if(!e.hadRecentInput)__perf.shift.push([e.startTime,e.value])});o('longtask',e=>__perf.long.push(e.duration));o('paint',e=>{if(e.name==='first-contentful-paint')__perf.fcp=e.startTime});document.addEventListener('DOMContentLoaded',()=>{let mark=()=>{if(!__perf.vis&&!document.documentElement.classList.contains('site-loading'))__perf.vis=performance.now()};new MutationObserver(mark).observe(document.documentElement,{attributes:true,attributeFilter:['class']});mark()});`});
 const paths=process.argv.length>3?process.argv.slice(3):['/','/about.html','/portfolio.html','/resume/moein-ghezelbash-fa.html','/blog/fa/','/blog/fa/dashboard-to-action/','/en/about.html','/blog/en/dashboard-to-action/'];const result=[];
 for(const path of paths){await cmd('Page.navigate',{url:'http://127.0.0.1:'+server.address().port+path}); await sleep(6500);const r=await cmd('Runtime.evaluate',{expression:`JSON.stringify((()=>{let x=__perf,s=0,max=0,first=0,last=0;for(let [t,v] of x.shift){if(t-last>=1000||t-first>=5000){s=0;first=t} s+=v;last=t;max=Math.max(max,s)}return {path:location.pathname,lcp:Math.round(x.lcp),element:x.element,cls:+max.toFixed(4),fcp:Math.round(x.fcp),reveal:Math.round(x.vis),longTaskExcess:Math.round(x.long.reduce((a,b)=>a+Math.max(0,b-50),0)),ready:document.readyState,loading:document.documentElement.classList.contains('site-loading'),overflow:document.documentElement.scrollWidth>innerWidth+1}})())`,returnByValue:true});const row=JSON.parse(r.result.value);if(row.path!==path||!row.lcp)throw new Error('No measurement '+path+' '+JSON.stringify(row));result.push(row);console.log(JSON.stringify(row));}
 fs.writeFileSync(process.argv[2],JSON.stringify(result,null,2)+'\n');
}
main().catch(e=>{console.error(e);process.exitCode=1}).finally(()=>{ws?.close();chrome?.kill();server.close();setTimeout(()=>{try{fs.rmSync(profile,{recursive:true,force:true})}catch{}},300)});
